module can_make_equal(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [31:0] arr_0,\n    input wire [31:0] arr_1,\n    input wire [31:0] arr_2,\n    input wire [31:0] arr_3,\n    input wire [31:0] arr_4,\n    input wire [31:0] arr_5,\n    input wire [31:0] arr_6,\n    input wire [31:0] arr_7,\n    input wire [3:0] len,\n    output reg result,\n    output reg done\n);\n    \n    localparam [2:0] IDLE = 3'b000;\n    localparam [2:0] COMPUTE_CORE = 3'b001;\n    localparam [2:0] COMPARE = 3'b010;\n    localparam [2:0] FINISHED = 3'b011;\n    \n    reg [2:0] state;\n    reg [2:0] next_state;\n    reg [3:0] index;\n    reg [31:0] current_num;\n    reg [31:0] reference_core;\n    reg core_valid;\n    reg compare_result;\n    \n    wire [31:0] core;\n    reg [31:0] temp_num;\n    \n    always @(*) begin\n        temp_num = current_num;\n        while (temp_num % 2 == 0 && temp_num != 0) begin\n            temp_num = temp_num >> 1;\n        end\n        while (temp_num % 3 == 0 && temp_num != 0) begin\n            temp_num = temp_num / 3;\n        end\n        core = temp_num;\n    end\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            index <= 4'd0;\n            current_num <= 32'd0;\n            reference_core <= 32'd0;\n            core_valid <= 1'b0;\n            compare_result <= 1'b1;\n            result <= 1'b0;\n            done <= 1'b0;\n        end else begin\n            state <= next_state;\n            \n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        compare_result <= 1'b1;\n                        index <= 4'd0;\n                    end\n                end\n                \n                COMPUTE_CORE: begin\n                    case (index)\n                        4'd0: current_num <= arr_0;\n                        4'd1: current_num <= arr_1;\n                        4'd2: current_num <= arr_2;\n                        4'd3: current_num <= arr_3;\n                        4'd4: current_num <= arr_4;\n                        4'd5: current_num <= arr_5;\n                        4'd6: current_num <= arr_6;\n                        4'd7: current_num <= arr_7;\n                        default: current_num <= 32'd0;\n                    endcase\n                    core_valid <= 1'b1;\n                end\n                \n                COMPARE: begin\n                    if (core_valid) begin\n                        if (index == 4'd0) begin\n                            reference_core <= core;\n                        end else if (core != reference_core) begin\n                            compare_result <= 1'b0;\n                        end\n                        \n                        if (index < len) begin\n                            index <= index + 4'd1;\n                        end\n                        core_valid <= 1'b0;\n                    end\n                end\n                \n                FINISHED: begin\n                    result <= compare_result;\n                    done <= 1'b1;\n                end\n            endcase\n        end\n    end\n    \n    always @(*) begin\n        case (state)\n            IDLE: begin\n                if (start && (len != 4'd0)) next_state = COMPUTE_CORE;\n                else next_state = IDLE;\n            end\n            \n            COMPUTE_CORE: next_state = COMPARE;\n            \n            COMPARE: begin\n                if ((index < len) && compare_result) next_state = COMPUTE_CORE;\n                else next_state = FINISHED;\n            end\n            \n            FINISHED: next_state = IDLE;\n            \n            default: next_state = IDLE;\n        endcase\n    end\n    \nendmodule